<?= $this->extend('layout') ?><?= $this->section('content') ?><h1 class="mb-3">Buat Penawaran</h1><form method="post" action="/quotations" class="card"><div class="card-body"><div class="row g-3"><div class="col-md-4"><label class="form-label">Perusahaan *</label><select name="company_id" required class="form-select"><option value="">Pilih perusahaan</option><?php foreach ($companies as $company): ?><option value="<?= $company['id'] ?>" <?= old('company_id') == $company['id'] ? 'selected' : '' ?>><?= esc($company['name']) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><label class="form-label">Nomor Penawaran *</label><input required name="quotation_no" class="form-control" value="<?= old('quotation_no', 'Q-' . date('Ymd-His')) ?>"></div><div class="col-md-4"><label class="form-label">Berlaku sampai</label><input type="date" name="valid_until" class="form-control" value="<?= old('valid_until') ?>"></div><div class="col-12"><label class="form-label">Judul *</label><input required name="title" class="form-control" value="<?= old('title') ?>"></div><div class="col-md-4"><label class="form-label">Nama customer</label><input name="customer_name" class="form-control"></div><div class="col-md-4"><label class="form-label">Telepon customer</label><input name="customer_phone" class="form-control"></div><div class="col-md-4"><label class="form-label">Pajak (%)</label><input type="number" step="0.01" name="tax_percent" class="form-control" value="0"></div><div class="col-12"><label class="form-label">Alamat customer</label><textarea name="customer_address" class="form-control"></textarea></div><div class="col-12"><label class="form-label">Item Produk</label><div class="table-responsive"><table class="table" id="items"><thead><tr><th>Produk</th><th width="120">Qty</th><th width="140">Harga</th><th width="120">Diskon %</th><th></th></tr></thead><tbody><tr><td><select name="items[0][product_id]" class="form-select"><option value="">Pilih produk</option><?php foreach ($products as $product): ?><option value="<?= $product['id'] ?>"><?= esc($product['name']) ?> - Rp <?= number_format((float)$product['selling_price'], 0, ',', '.') ?></option><?php endforeach; ?></select></td><td><input name="items[0][quantity]" type="number" step="0.01" min="0" class="form-control" value="1"></td><td><input name="items[0][unit_price]" type="number" step="0.01" min="0" class="form-control" value="0"></td><td><input name="items[0][discount_percent]" type="number" step="0.01" min="0" max="100" class="form-control" value="0"></td><td><button type="button" class="btn btn-outline-secondary" onclick="this.closest('tr').remove()">Hapus</button></td></tr></tbody></table></div><button type="button" class="btn btn-sm btn-outline-primary" onclick="addItem()">Tambah item</button></div><div class="col-12"><label class="form-label">Catatan</label><textarea name="notes" class="form-control"></textarea></div></div></div><div class="card-footer"><a href="/quotations" class="btn btn-light">Batal</a> <button class="btn btn-primary">Simpan Penawaran</button></div></form><script>let n=1;function addItem(){const row=document.querySelector('#items tbody tr').cloneNode(true);row.querySelectorAll('[name]').forEach(e=>e.name=e.name.replace(/items\[\d+\]/,'items['+n+']'));row.querySelectorAll('input').forEach(e=>{if(e.name.includes('quantity'))e.value=1;if(e.name.includes('unit_price')||e.name.includes('discount'))e.value=0});document.querySelector('#items tbody').appendChild(row);n++}</script><?= $this->endSection() ?>
